def solve():
    import sys
    lines = sys.stdin.read().strip().splitlines()
    q = int(lines[0]) if lines else 0
    in_stack, out_stack = [], []
    out = []

    def transfer():
        while in_stack:
            out_stack.append(in_stack.pop())

    for line in lines[1:1 + q]:
        parts = line.split()
        if parts[0] == 'push':
            in_stack.append(int(parts[1]))
        elif parts[0] == 'pop':
            if not out_stack:
                transfer()
            out.append(str(out_stack.pop()))
        elif parts[0] == 'peek':
            if not out_stack:
                transfer()
            out.append(str(out_stack[-1]))
        elif parts[0] == 'empty':
            out.append('true' if not in_stack and not out_stack else 'false')
    print('\n'.join(out))


