def solve():
    import sys
    from collections import deque
    lines = sys.stdin.read().strip().splitlines()
    q = int(lines[0]) if lines else 0
    q1, q2 = deque(), deque()
    out = []
    for line in lines[1:1 + q]:
        parts = line.split()
        if parts[0] == 'push':
            q1.append(int(parts[1]))
        elif parts[0] == 'pop':
            while len(q1) > 1:
                q2.append(q1.popleft())
            out.append(str(q1.popleft()))
            q1, q2 = q2, q1
        elif parts[0] == 'top':
            while len(q1) > 1:
                q2.append(q1.popleft())
            out.append(str(q1[0]))
            q2.append(q1.popleft())
            q1, q2 = q2, q1
        elif parts[0] == 'empty':
            out.append('true' if not q1 else 'false')
    print('\n'.join(out))


